// Lattice Panorama - a flight through an endless lattice of beams that
// vibrate like plucked strings, seen as a full 360-degree panorama.
// Parametric (u,v), animated. Seam-free.
//
// HOW IT CLOSES: every point of the surface looks along a direction of
// space: u turns the gaze all the way around (0..360 degrees), v tilts it
// between straight down and straight up, and the picture is a ray marched
// through the lattice along that direction. u = 0 and u = 1 are the same
// direction, and looking straight down/up every u sees the same thing, so
// there is no seam and no pinch at the poles.
//   PITCH_LOOP = 1: v goes down -> up -> down: closes on every surface
//                   (torus, Klein bottle, Moebius band...).
//   PITCH_LOOP = 0: v goes once from down to up: an exact panorama on
//                   sphere-like surfaces whose v runs from pole to pole.
// Dock colors: u_col1 = light of the beams (white = three tints),
//              u_col2 = fog.

const float PITCH_LOOP = 1.0;  // see above
const float SPEED    = 0.3;    // flight speed (lattice cells per second)
const float TURN     = 0.015;  // slow turning of the view (turns per second)
const float CELL     = 2.0;    // spacing of the beams
const float BEAM     = 0.14;   // beam radius                           [0.05 .. 0.4]
const float NODE     = 0.3;    // radius of the joints (0 = none)       [0 .. 0.6]
const float WAVE     = 0.22;   // vibration of the beams                [0 .. 0.4]
const float FOG      = 0.07;   // fog density                           [0 .. 0.3]
const int   STEPS    = 72;     // ray steps: quality against speed      [32 .. 128]

// distance to the lattice; fam = which family is nearest
// (0 beams along x, 1 along y, 2 along z, 3 joints)
float lattice(vec3 p, float time, out float fam) {
    float h = 0.5 * CELL;
    // each beam vibrates between two joints: zero offset at the joints
    vec3 s = sin(TAU * p / CELL);
    vec3 amp = WAVE * sin(time * vec3(1.3, 1.7, 2.1) + vec3(0.0, 2.0, 4.0));
    vec2 qx = mod(p.yz + vec2(1.0, 0.6) * amp.x * s.x + h, CELL) - h;
    vec2 qy = mod(p.zx + vec2(1.0, -0.6) * amp.y * s.y + h, CELL) - h;
    vec2 qz = mod(p.xy + vec2(-0.7, 1.0) * amp.z * s.z + h, CELL) - h;
    vec3 qn = mod(p + h, CELL) - h;
    float dx = length(qx) - BEAM;
    float dy = length(qy) - BEAM;
    float dz = length(qz) - BEAM;
    float dn = NODE > 0.0 ? length(qn) - NODE : 1.0e9;
    float dist = dx;
    fam = 0.0;
    if (dy < dist) { dist = dy; fam = 1.0; }
    if (dz < dist) { dist = dz; fam = 2.0; }
    if (dn < dist) { dist = dn; fam = 3.0; }
    return dist;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord / iResolution.xy;
    float time = iTime;

    // gaze direction from (u, v)
    float tri = 1.0 - abs(2.0 * fract(uv.y) - 1.0);        // 0 -> 1 -> 0 along v
    float w = PITCH_LOOP > 0.5 ? tri : clamp(uv.y, 0.0, 1.0);
    float pitch = PI * (w - 0.5);
    float yaw = TAU * (uv.x + TURN * time);
    vec3 dir = vec3(cos(pitch) * sin(yaw), sin(pitch), cos(pitch) * cos(yaw));

    // the camera flies along z in the free channel between the beams
    float h = 0.5 * CELL;
    vec3 ro = vec3(h, h, SPEED * CELL * time);

    float t = 0.0;
    float fam = 0.0;
    float hit = 0.0;
    float glow = 0.0;
    for (int i = 0; i < STEPS; i++) {
        float dist = lattice(ro + dir * t, time, fam);
        glow += 1.0 / (1.0 + 60.0 * dist * dist);
        if (dist < 0.001 + 0.002 * t) { hit = 1.0; break; }
        t += 0.8 * dist;
        if (t > 45.0) break;
    }
    glow /= float(STEPS);

    vec3 col = u_col2;
    if (hit > 0.5) {
        vec3 p = ro + dir * t;
        const vec2 k = vec2(0.002, 0.0);
        float tmp;
        vec3 n = normalize(vec3(
            lattice(p + k.xyy, time, tmp) - lattice(p - k.xyy, time, tmp),
            lattice(p + k.yxy, time, tmp) - lattice(p - k.yxy, time, tmp),
            lattice(p + k.yyx, time, tmp) - lattice(p - k.yyx, time, tmp)));
        vec3 tint = fam < 0.5 ? vec3(1.0, 0.72, 0.45)
                  : fam < 1.5 ? vec3(0.5, 0.78, 1.0)
                  : fam < 2.5 ? vec3(0.78, 1.0, 0.55)
                  :             vec3(1.0, 0.95, 0.9);
        float facing = abs(dot(n, dir));
        float lit = 0.25 + 0.75 * facing;                    // light from the eye
        float edge = pow(1.0 - facing, 3.0);                 // bright silhouettes
        vec3 surf = u_col1 * tint * lit + edge * 0.6 * mix(tint, vec3(1.0), 0.5);
        col = mix(surf, u_col2, 1.0 - exp(-FOG * t));
    }
    // neon haze from the beams the ray passed close to
    col += u_col1 * glow * 0.6;

    fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}
